solution.solution.cpp:
#include <numeric>

struct Fraction
{
    int num{ 0 };
    int den{ 1 };
};

Fraction reduce(Fraction f)
{
    const int divisor{ std::gcd(f.num, f.den) };
    if (divisor != 0)
    {
        f.num /= divisor;
        f.den /= divisor;
    }
    return f;
}

Fraction add(Fraction a, Fraction b)
{
    return reduce(Fraction{ a.num * b.den + b.num * a.den, a.den * b.den });
}

Fraction multiply(Fraction a, Fraction b)
{
    return reduce(Fraction{ a.num * b.num, a.den * b.den });
}

double toDouble(Fraction f)
{
    return static_cast<double>(f.num) / f.den;
}

unitTests:
TEST("reduce") { const Fraction f{ reduce(Fraction{ 6, 8 }) }; CHECK_EQ(f.num, 3); CHECK_EQ(f.den, 4); const Fraction g{ reduce(Fraction{ 5, 7 }) }; CHECK_EQ(g.num, 5); CHECK_EQ(g.den, 7); }
TEST("add") { const Fraction s{ add(Fraction{ 3, 4 }, Fraction{ 5, 6 }) }; CHECK_EQ(s.num, 19); CHECK_EQ(s.den, 12); }
TEST("add reduces its answer") { const Fraction s{ add(Fraction{ 1, 4 }, Fraction{ 1, 4 }) }; CHECK_EQ(s.num, 1); CHECK_EQ(s.den, 2); }
TEST("multiply") { const Fraction p{ multiply(Fraction{ 3, 4 }, Fraction{ 5, 6 }) }; CHECK_EQ(p.num, 5); CHECK_EQ(p.den, 8); }
TEST("toDouble") { CHECK_NEAR(toDouble(Fraction{ 3, 4 }), 0.75, 1e-12); CHECK_NEAR(toDouble(Fraction{ 1, 3 }), 0.333333333, 1e-6); }

